import { Group, Mesh, BoxGeometry, PlaneGeometry, CircleGeometry, MeshStandardNodeMaterial, MeshBasicNodeMaterial, MeshPhysicalNodeMaterial, PointLight, Color, DoubleSide } from 'three/webgpu';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const colors = config.intent?.visualSpec?.colors ?? { ink: '#16161d', paper: '#e8ecf2', accent: '#ff2a38', surface: '#0b0b10' };
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [{ text: 'Journal 2', role: 'headline', typography: { fontSize: 39, weight: 400 } }];

  const root = new Group();
  root.name = 'journal-card-2-label';

  // --- base plate (slightly extruded, PBR machined metal look) ---
  const plateW = 1.7, plateH = 0.62, plateD = 0.06;
  const plateGeo = new BoxGeometry(plateW, plateH, plateD);
  const plateMat = new MeshStandardNodeMaterial({
    color: new Color(colors.ink),
    roughness: 0.55,
    metalness: 0.42,
  });
  const plate = new Mesh(plateGeo, plateMat);
  plate.position.set(0, 0, 0);
  root.add(plate);

  // --- accent edge strip (<=10% of frame, thin bottom rail) ---
  const edgeGeo = new BoxGeometry(plateW, 0.03, plateD + 0.004);
  const edgeMat = new MeshStandardNodeMaterial({
    color: new Color(colors.accent),
    roughness: 0.5,
    metalness: 0.3,
    emissive: new Color(colors.accent),
    emissiveIntensity: 0.9,
  });
  const edge = new Mesh(edgeGeo, edgeMat);
  edge.position.set(0, -plateH / 2 + 0.015, plateD / 2 + 0.002);
  root.add(edge);

  // --- art plane (feature card image) ---
  const artGeo = new PlaneGeometry(1.5, 0.4);
  const artMat = new MeshBasicNodeMaterial({ color: new Color(colors.surface), side: DoubleSide });
  const art = new Mesh(artGeo, artMat);
  art.position.set(0, 0.03, plateD / 2 + 0.031);
  root.add(art);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      artMat.map = tex;
      artMat.color.set('#ffffff');
      artMat.needsUpdate = true;
    }).catch(() => {});
  }

  // --- headline text: "Journal 2" ---
  const headlineItem = items.find((i) => i.role === 'headline') ?? items[0];
  const headline = ctx.fontAtlas.createText(headlineItem?.text ?? 'Journal 2', {
    fontSize: headlineItem?.typography?.fontSize ?? 39,
    color: colors.paper,
    align: 'left',
  });
  headline.position.set(-plateW / 2 + 0.14, -plateH / 2 + 0.09, plateD / 2 + 0.04);
  root.add(headline);

  // --- contact shadow (grounding) ---
  const shadowGeo = new CircleGeometry(plateW * 0.62, 32);
  const shadowMat = new MeshBasicNodeMaterial({ color: new Color('#000000'), transparent: true, opacity: 0.42 });
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -plateH / 2 - 0.02, 0.02);
  root.add(shadow);

  // --- local rim/accent light (scene supplies ambient 0.6 + key 1.2) ---
  const rim = new PointLight(new Color(colors.accent), 0.7, 4, 2);
  rim.position.set(0.6, 0.4, -1.0);
  root.add(rim);

  // --- cinematic primitive: parallax-scroll ---
  const primResults = [];
  const primitiveConfigs = config.cinematicPrimitives ?? [{ name: 'parallax-scroll', params: { intensity: 0.25 }, trigger: 'scroll' }];
  for (const p of primitiveConfigs) {
    const fn = ctx.primitives[p.name];
    if (typeof fn === 'function') {
      const res = fn(root, p.params ?? {});
      if (res) primResults.push(res);
    }
  }

  // --- motion state ---
  const baseY = root.position.y;
  let hoverTl = null;
  let pressTl = null;

  const onHoverIn = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(root.position, { y: baseY + 0.15, duration: 0.5, ease: 'power3.out' }, 0);
    hoverTl.to(edgeMat, { emissiveIntensity: 1.4, duration: 0.3, ease: 'power2.out' }, 0);
    hoverTl.to(root.scale, { x: 1.02, y: 1.02, z: 1.02, duration: 0.5, ease: 'power3.out' }, 0);
  };

  const onHoverOut = () => {
    if (hoverTl) hoverTl.kill();
    hoverTl = gsap.timeline();
    hoverTl.to(root.position, { y: baseY, duration: 0.6, ease: 'power4.out' }, 0);
    hoverTl.to(edgeMat, { emissiveIntensity: 0.9, duration: 0.3, ease: 'power2.out' }, 0);
    hoverTl.to(root.scale, { x: 1, y: 1, z: 1, duration: 0.6, ease: 'power4.out' }, 0);
  };

  const onClick = () => {
    if (pressTl) pressTl.kill();
    pressTl = gsap.timeline();
    pressTl.to(root.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out' });
    pressTl.to(root.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.4, ease: 'power2.out' });
    ctx.emit('hub-journal.select', { nodeId: config.id ?? 'hub-journal-card-0-label' });
  };

  root.userData.handlers = {
    pointerover: onHoverIn,
    pointerout: onHoverOut,
    click: onClick,
  };

  root.userData.cleanup = () => {
    if (hoverTl) hoverTl.kill();
    if (pressTl) pressTl.kill();
    for (const r of primResults) {
      if (r.timeline) r.timeline.kill();
      if (typeof r.cleanup === 'function') r.cleanup();
    }
    plateGeo.dispose();
    plateMat.dispose();
    edgeGeo.dispose();
    edgeMat.dispose();
    artGeo.dispose();
    artMat.dispose();
    if (artMat.map) artMat.map.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();
    root.remove(rim);
    if (headline.userData?.cleanup) headline.userData.cleanup();
  };

  return root;
}
